{
  "findings": [
    {
      "title": "Inconsistent randomization ratio: text says 2:1 but schema and sample size say 1:1",
      "page": 14,
      "quote": "randomized 2:1 to receive either AMG 510 or docetaxel.",
      "severity": "critical"
    },
    {
      "title": "Inconsistent sample size: 330 vs 396 and 165 per arm",
      "page": 17,
      "quote": "Approximately 396 subjects ... with approximately 165 subjects in each of the 2 treatment groups.",
      "severity": "critical"
    },
    {
      "title": "Inconsistent AMG 510 dose: 1200 mg vs 960 mg",
      "page": 17,
      "quote": "AMG 510 will be dispensed at 1200 mg once daily (QD) orally (PO)",
      "severity": "critical"
    },
    {
      "title": "Inconsistent OS primary analysis timing: 9 months vs 3 months after PFS primary analysis",
      "page": 17,
      "quote": "which is expected to be at approximately 9 months after PFS primary analysis.",
      "severity": "major"
    },
    {
      "title": "Inconsistent PFS interim analysis event count: 160 vs 70% of 230 (161)",
      "page": 16,
      "quote": "An IA of PFS for superiority is planned when approximately 70% (160 events) of the total PFS events have been observed",
      "severity": "minor"
    },
    {
      "title": "Inconsistent OS interim analysis event count: 107 vs 32% of 198 (63)",
      "page": 20,
      "quote": "an administrative interim summary for OS will be performed with approximately 107 OS events (~32% maturity) observed.",
      "severity": "major"
    },
    {
      "title": "Inconsistent OS analysis event count: 175 vs 53% of 198 (105)",
      "page": 20,
      "quote": "after 175 OS events (~53% maturity) have been observed",
      "severity": "major"
    },
    {
      "title": "Inconsistent OS primary analysis event count: 198 vs 60% of 330 (198) but 60% of 396 is 238",
      "page": 17,
      "quote": "The OS primary analysis will occur when at least 198 OS events (~60% maturity) have been observed",
      "severity": "major"
    },
    {
      "title": "Inconsistent sample size rationale: 330 with 1:1 randomization but text says 2:1",
      "page": 20,
      "quote": "which is approximately 330 subjects with 1:1 randomization ratio into the AMG 510 arm and the docetaxel arm.",
      "severity": "critical"
    },
    {
      "title": "Inconsistent PFS primary analysis timing: 19 months vs 13 months to reach 160 events",
      "page": 20,
      "quote": "approximately 19 months will be required to reach 230 PFS events, and 13 months will be required to reach 70% (160) of the target PFS events.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent crossover timing: page 14 says after independent central confirmation, but page 15 says consent to crossover",
      "page": 14,
      "quote": "they will be given the opportunity to crossover and receive AMG 510.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent treatment beyond progression: page 15 says 'in select cases' but page 14 says 'will continue'",
      "page": 15,
      "quote": "In select cases, subjects may continue on treatment following radiologic progression",
      "severity": "minor"
    }
  ]
}
